/// <summary>
/// MPJ_21713_METPostProductReceiptsEntity
/// This class posts packing slips for purchase orders as per the data in METPOReceipts entity.
/// </summary>
class METPostProductReceiptService extends SysOperationServiceBase
{
    List         purchLineList = new List(Types::Record);
    str          errorMessage;
    str          infologMessage;

}

Method.Source:
    /// <summary>
    /// Executes the business logic
    /// </summary>
    public void processLines()
    {
        METPOReceipt    metPOReceipt, metPOReceiptLoc;
        PurchLine       purchLine;
        PackingSlipId   packingSlipIdCur;
        utcdatetime     productReceiptDate;
        boolean         isPostingSuccessful;
        #OCCRetryCount
        
        try
        {
            while select metPOReceipt
                group by PurchaseOrderNumber, OrderVendorAccountNumber, ProductReceiptDate, PackingSlipId, ProductNumber, Quantity, InventSiteId
                where metPOReceipt.Processed == NoYes::No
                   && metPOReceipt.Error == NoYes::Yes
            {

                if((packingSlipIdCur != metPOReceipt.PackingSlipId) &&  packingSlipIdCur) //Check if new PO receipt
                {
                    select firstonly metPOReceiptLoc
                        where metPOReceiptLoc.PackingSlipId == packingSlipIdCur
                            && metPOReceiptLoc.ProductReceiptDate == productReceiptDate;
                        
                    isPostingSuccessful = this.postProductReceipt(metPOReceiptLoc);
                    this.updatePOReceiptLines(isPostingSuccessful, metPOReceiptLoc);
                    this.clearLinesFromList(purchLineList);
                }

                packingSlipIdCur = metPOReceipt.PackingSlipId;
                productReceiptDate = metPOReceipt.ProductReceiptDate;

                purchLine = this.getPurchLine(metPOReceipt);

                if(purchLine.RecId && !metPOReceipt.Error)
                {
                    this.addPOLinesToList(purchLine);  //add lines to list
                }
            }
            if(packingSlipIdCur)  //Check if new PO receipt
            {
                select firstonly metPOReceiptLoc
                            where metPOReceiptLoc.PackingSlipId == packingSlipIdCur
                               && metPOReceiptLoc.ProductReceiptDate == productReceiptDate;
                        
                isPostingSuccessful = this.postProductReceipt(metPOReceiptLoc);
                this.updatePOReceiptLines(isPostingSuccessful, metPOReceiptLoc);
                this.clearLinesFromList(purchLineList);
            }

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::CLRError)
        {
            errorMessage    = METConstants::emptyString;
            System.Exception ex = ClrInterop::getLastException();
            if (ex != null)
            {
                ex = ex.get_InnerException();
                if (ex != null)
                {
                    errorMessage += ex.Message + ex.ToString();
                }
            }
            
            this.updateLogLine(errorMessage, infologMessage, metPOReceipt);
        }
        catch(Exception::Error)
        {
            errorMessage    = METConstants::emptyString;

            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            if (ex != null)
            {
                errorMessage += ex.Message + ex.ToString();
            }
            
            this.updateLogLine(errorMessage, infologMessage, metPOReceipt);
        }
    }

    /// <summary>
    /// Deletes purchase lines from the purchaseLineList.
    /// </summary>
    /// <param name = "_purchLineList">purchase line list.</param>
    public void clearLinesFromList(List _purchLineList)
    {
        ListIterator    listIterator = new ListIterator(_purchLineList);

        while(listIterator.more())
        {
            listIterator.delete();
        }
    }

    /// <summary>
    /// Adds purchase lines to the purchaseLineList.
    /// </summary>
    /// <param name = "_purchLine">purchase line record.</param>
    /// <returns>purchase lines list.</returns>

    public List addPOLinesToList(PurchLine _purchLine)
    {
        
        purchLineList.addEnd(_purchLine);

        return purchLineList; 
    }

    /// <summary>
    /// updates the metPOReceipt records based on the PO receipts posting
    /// </summary>
    /// <param name = "_isPostingSuccessful"> indicates if PO recipting is successful</param>
    /// <param name = "_metPOReceipt"> the metPORecipt buffer to be updated for a specific product receipt</param>
    public void updatePOReceiptLines(boolean _isPostingSuccessful, METPOReceipt _metPOReceipt)
    {
        METPOReceipt metPOReceiptLoc;

        if(_isPostingSuccessful)
        {
            delete_from metPOReceiptLoc
                where metPOReceiptLoc.PackingSlipId == _metPOReceipt.PackingSlipId
                    && metPOReceiptLoc.ProductReceiptDate == _metPOReceipt.ProductReceiptDate;

        }
        else
        {
            ttsbegin;
            while select forupdate metPOReceiptLoc
                where metPOReceiptLoc.PackingSlipId == _metPOReceipt.PackingSlipId
                   && metPOReceiptLoc.ProductReceiptDate == _metPOReceipt.ProductReceiptDate
            {
                metPOReceiptLoc.Error = NoYes::Yes;
                metPOReceiptLoc.ErrorMessage = _metPOReceipt.ErrorMessage;
                metPOReceiptLoc.doUpdate();
            }
            ttscommit;
        }
        

    }

    /// <summary>
    /// Method to identify the purchase line against which the quantity will be recieved
    /// </summary>
    /// <param name = "_metPOReceipt">metPOReceipt buffer</param>
    /// <returns>purchase line that matches the criteria</returns>
    public PurchLine getPurchLine(METPOReceipt _metPOReceipt)
    {
        PurchLine                       purchLine, purchLineCount, purchLineToSplit;
        PurchQty                        qtyToSplit, purchqty;
        MetItemSiteSettingsSetup        itemSiteSettingsSetup;
        UnitOfMeasureSymbol             unitIDFrom;
        UnitOfMeasureSymbol             unitIDTo;
        UnitOfMeasureConversionFactor   conversionFactor;
        InventDim                       inventDim;

        select count(RecId) from purchLineCount
            where purchLineCount.PurchId == _metPOReceipt.PurchaseOrderNumber
                    && purchLineCount.ItemId == _metPOReceipt.ProductNumber
                    && purchLineCount.PurchStatus == PurchStatus::Backorder;

        select firstonly UnitId from itemSiteSettingsSetup
                    where itemSiteSettingsSetup.ItemId == _metPOReceipt.ProductNumber
                        && itemSiteSettingsSetup.InventSiteId == _metPOReceipt.InventSiteId;

        if(purchLineCount.RecId >= 1)
        {
            select forupdate firstonly purchLine
                    where purchLine.PurchId == _metPOReceipt.PurchaseOrderNumber
                        && purchLine.ItemId == _metPOReceipt.ProductNumber
                        && purchLine.PurchStatus == PurchStatus::Backorder
                    join RecId from inventDim
                        where inventDim.inventDimId == purchLine.InventDimId
                           && inventDim.InventSiteId == _metPOReceipt.InventSiteId;

            if(purchLine.RecId)
            {
                if(_metPOReceipt.Quantity == 0)
                {
                    ttsbegin;

                    purchLine.PurchReceivedNow = 0;
                    purchLine.modifiedField(fieldNum(PurchLine, PurchReceivedNow));
                    purchLine.update();

                    ttscommit;

                    _metPOReceipt.Error = NoYes::No;

                    return purchLine;
                }
                else
                {
                    unitIDFrom = itemSiteSettingsSetup.UnitId;
                    unitIDTo = purchLine.PurchUnit;

                    if(unitIDFrom == unitIDTo)
                    {
                        purchqty = _metPOReceipt.Quantity;
                    }
                    else if(unitIDFrom == METConstants::emptyString)
                    {
                        purchqty = _metPOReceipt.Quantity;
                    }
                    else
                    {
                        conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(unitIDFrom).RecId,
                            UnitOfMeasure::findBySymbol(unitIDTo).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId)
                            .Factor, 0);

                        if(conversionFactor != 0)
                        {
                            purchqty = any2int(_metPOReceipt.Quantity * conversionFactor);
                        }
                        else
                        {
                            conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                                UnitOfMeasure::findBySymbol(unitIDTo).RecId,
                                UnitOfMeasure::findBySymbol(unitIDFrom).RecId,
                                EcoResProduct::findByProductNumber(purchLine.ItemId).RecId)
                                .Factor, 0);

                            if(conversionFactor != 0)
                            {
                                purchqty = any2int(_metPOReceipt.Quantity / conversionFactor);
                            }
                            else
                            {
                                purchqty = _metPOReceipt.Quantity;
                            }
                        }
                    }

                }
                
                if(purchLine.PurchQty >= purchqty) //Check if quantities match
                {
                    ttsbegin;
                    purchLine.PurchReceivedNow = purchqty;
                    purchLine.modifiedField(fieldNum(PurchLine, PurchReceivedNow));
                    purchLine.update();
                    ttscommit;

                    _metPOReceipt.Error = NoYes::No;

                    return purchLine;
                }
                else
                {
                    if(purchLineCount.RecId > 1)  //try to split the lines
                    {
                        qtyToSplit = purchqty - purchLine.PurchQty;

                        select firstonly RecId from purchLineToSplit
                            where purchLineToSplit.PurchId == _metPOReceipt.PurchaseOrderNumber
                                && purchLineToSplit.ItemId == _metPOReceipt.ProductNumber
                                && purchLineToSplit.PurchQty >= qtyToSplit
                                && purchLineToSplit.LineNumber != purchLine.LineNumber;

                        if(purchLineToSplit.RecId)
                        {
                            ttsbegin;
                            purchLineToSplit.selectForUpdate(true);
                            purchLineToSplit.RemainPurchPhysical = qtyToSplit;
                            purchLineToSplit.modifiedField(fieldNum(PurchLine, RemainPurchPhysical));
                            purchLineToSplit.update();

                            purchLine.PurchReceivedNow = purchqty;
                            purchLine.modifiedField(fieldNum(PurchLine, PurchReceivedNow));
                            purchLine.update();
                            ttscommit;
                            
                            _metPOReceipt.Error = NoYes::No;

                            return purchLine;
                        }

                    }
                    else if((purchLineCount.RecId == 1))
                    {
                        if (purchLine.OverDeliveryPct > 0) //Check if overdelivery is allowed
                        {
                            Qty maxReceivedQty = purchLine.PurchQty * (1 + purchLine.OverDeliveryPct / 100);

                            if(maxReceivedQty >= purchqty)
                            {
                                ttsbegin;
                                purchLine.PurchReceivedNow = purchqty;
                                purchLine.modifiedField(fieldNum(PurchLine, PurchReceivedNow));
                                purchLine.update();
                                ttscommit;

                                _metPOReceipt.Error = NoYes::No;

                                return purchLine;
                            }
                        }
                    }
                    else
                    {
                        _metPOReceipt.Error = NoYes::Yes;
                        _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber, _metPOReceipt.OrderVendorAccountNumber);
                    }
                }
            }
            else
            {
                _metPOReceipt.Error = NoYes::Yes;
                _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber, _metPOReceipt.OrderVendorAccountNumber);
            }
        }
        else
        {
            _metPOReceipt.Error = NoYes::Yes;
            _metPOReceipt.ErrorMessage = strFmt("@MET:NoLinesFoundValidation", _metPOReceipt.ProductNumber, _metPOReceipt.PurchaseOrderNumber, _metPOReceipt.OrderVendorAccountNumber);
        }

        return purchLine;
    }

    /// <summary>
    /// method post product receipt for a given list of purchase lines
    /// </summary>
    /// <param name = "_metPOReceipt">metPOReceipt buffer</param>
    /// <returns>boolean value indicating if the PO receipting is successful </returns>
    public boolean postProductReceipt(METPOReceipt _metPOReceipt)
    {
        boolean         ret = true;
        PurchTable      purchTable = PurchTable::find(_metPOReceipt.PurchaseOrderNumber);
        PurchFormLetter purchFormLetter = PurchFormLetter::construct(DocumentStatus::PackingSlip);

        try
        {
            ttsbegin;
            purchFormLetter.createFromLines(true);
            purchFormLetter.parmLineList(purchLineList.pack());
            purchFormLetter.update(purchTable, _metPOReceipt.PackingSlipId, DateTimeUtil::date(_metPOReceipt.ProductReceiptDate), PurchUpdate::ReceiveNow);
            ttscommit;
        }
        catch(Exception::Error)
        {
            _metPOReceipt.Error = NoYes::Yes;
            errorMessage    = METConstants::emptyString;

            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            if (ex != null)
            {
                errorMessage += ex.Message + ex.ToString();
            }
            
            this.updateLogLine(errorMessage, infologMessage, _metPOReceipt);
            ret = false;
        }
        return ret;
    }

    /// <summary>
    /// Gets the latest infolog error message
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

    /// <summary>
    /// update the error message to metPORecipts buffer
    /// </summary>
    /// <param name = "_mbsErrorMsg">actual error message</param>
    /// <param name = "_mbsInfologMsg">infolog error message</param>
    /// <param name = "_metPOReceipts">the metPOReceipt buffer to be updated with the error message </param>
    private void updateLogLine(str _mbsErrorMsg, str _mbsInfologMsg, METPOReceipt _metPOReceipts)
    {

        // if log header is available use the global variable to update the current log line to the below
        // status
        if(_metPOReceipts.RecId)
        {
            ttsbegin;
            _metPOReceipts.selectForUpdate(true);
            _metPOReceipts.ErrorMessage  = _mbsErrorMsg + METConstants::LineBreak + _mbsInfologMsg;
            _metPOReceipts.Error  = NoYes::Yes;
            _metPOReceipts.doUpdate();
            ttscommit;
        }

    }
